import{_ as r,o as e,c as o,a6 as a}from"./chunks/framework.B_q3ZJNF.js";const T=JSON.parse('{"title":"关于本课程","description":"","frontmatter":{},"headers":[],"relativePath":"proxy-software-course/about.md","filePath":"proxy-software-course/docs/about.md"}'),d={name:"proxy-software-course/about.md"};function n(s,t,l,i,c,h){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="关于本课程" tabindex="-1">关于本课程 <a class="header-anchor" href="#关于本课程" aria-label="Permalink to &quot;关于本课程&quot;">​</a></h1><p><strong>当应用把一个目标地址交给 Clash 类软件后，连接究竟经过哪些判断与搬运？</strong> 这是贯穿全书的主线问题——十章的全部内容，就是这句问题的完整答案。</p><h2 id="课程概况" tabindex="-1">课程概况 <a class="header-anchor" href="#课程概况" aria-label="Permalink to &quot;课程概况&quot;">​</a></h2><p>《代理软件实现原理：从一条 TCP 隧道到 mini-proxy》面向<strong>会 TypeScript、用过代理工具的开发者</strong>：你知道 Promise、判别联合、URL 与 HTTP 请求头这些基础，也用过系统代理或规则型代理工具，但裸 TCP socket、HTTP 正向代理协议、SOCKS5 二进制握手、背压与半关闭、DNS 与路由的先后顺序，这些通常都被工具封装得看不见。</p><p>课程由一句主题输入生成：<strong>「clash 等代理软件的原理是什么，怎么自己写一个代理软件」</strong>。全书 10 章、3 个分部，全部 10 章完成生成、无降级章、无阻断章。每一章都不只是讲解协议，而是把对应的行为亲手实现成 companion 工程 <code>companion/</code> 里可以运行、可以测试的 TypeScript 代码。</p><p>最终产物：<strong>一个双入口（HTTP 正向代理 + SOCKS5）、三出站（DIRECT / REJECT / SOCKS5 上游）、84 项测试全绿的本地代理</strong>，由 9 个章节测试文件覆盖 HTTP、CONNECT、SOCKS5、拒绝规则与上游 SOCKS5 链的 <code>127.0.0.1</code> 端到端验证。</p><h2 id="能力阶梯-学到第几章-你能做什么" tabindex="-1">能力阶梯：学到第几章，你能做什么 <a class="header-anchor" href="#能力阶梯-学到第几章-你能做什么" aria-label="Permalink to &quot;能力阶梯：学到第几章，你能做什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章</th><th>学完这一章，你能…</th></tr></thead><tbody><tr><td>1. 代理不是魔法：先画清一条连接</td><td>用入口、路由、出站三段模型解释正向代理，并区分系统代理、TUN、反向代理与 VPN</td></tr><tr><td>2. HTTP 正向代理：改写请求与打通 CONNECT</td><td>实现 absolute-form 改写，并用 CONNECT 为 HTTPS 建立不解密内容的 TCP 隧道——<strong>HTTP 入口能改写 absolute-form 并为 CONNECT 返回 200 后双向转发</strong></td></tr><tr><td>3. SOCKS5：把目标地址装进二进制握手</td><td>实现 NO AUTH 方法协商与 CONNECT 请求，正确编解码 IPv4、域名、IPv6 地址帧并处理分片——<strong>SOCKS5 入口支持 NO AUTH + CONNECT 和三种地址类型，并显式拒绝不支持的命令</strong></td></tr><tr><td>4. 双向搬运：背压、半关闭与清理</td><td>实现不会无界缓存、不会把单向 FIN 当成整条连接结束的双向 relay——<strong>relay 用双向 pipe 传播背压，用 end 传播半关闭，并在错误或关闭时只清理一次</strong></td></tr><tr><td>5. 规则引擎：第一条命中为什么决定一切</td><td>从连接元数据实现 DOMAIN、DOMAIN-SUFFIX、IPv4 CIDR、PORT 与 MATCH 的确定性决策——<strong>纯函数 route 按顺序返回 DIRECT、REJECT 或 PROXY</strong></td></tr><tr><td>6. DNS 在哪里发生：域名规则与 IP 规则的拉扯</td><td>实现 preserve-domain 与 resolve-first 两种策略——<strong>planRoute 根据策略决定解析时机，返回决策与 dialTarget，所有 DNS 副作用可注入</strong></td></tr><tr><td>7. 出站适配器：直连、拒绝与再套一层 SOCKS5</td><td>用统一 Dialer 接口实现 DIRECT、REJECT 和 SOCKS5 上游——<strong>三种出站共享 Dialer 契约，SOCKS5 客户端完成协商、CONNECT 与响应校验</strong></td></tr><tr><td>8. 配置先失败：不要让错误规则静默上线</td><td>从 unknown JSON 严格收窄 ProxyConfig——<strong>parseProxyConfig 返回有效配置或完整错误数组，并校验规则与出站的交叉引用</strong></td></tr><tr><td>9. 组装运行时：两个入口，共用一条决策管线</td><td>让 HTTP 与 SOCKS5 入口共享 route-DNS-dial-relay——<strong>createProxyRuntime 启动双入口并共享连接函数，返回实际端口、事件和可等待的 close</strong></td></tr><tr><td>10. 收官：验证整条链，也看清离 Clash 还有多远</td><td>用本地端到端矩阵证明已实现能力——<strong>HTTP、CONNECT、SOCKS5、REJECT 与 SOCKS5 上游链在纯本机拓扑中全部通过，并形成生产差异表</strong></td></tr></tbody></table><h2 id="权威事实来源" tabindex="-1">权威事实来源 <a class="header-anchor" href="#权威事实来源" aria-label="Permalink to &quot;权威事实来源&quot;">​</a></h2><p>本课程的协议与行为断言以下列文档为核实入口，测试自洽不替代事实正确。<strong>内容截至 2026-08-28</strong>：协议、标准与 Node.js 行为类事实以下表来源为准，超出此日期的规范修订或运行时变更不在覆盖范围内。</p><table tabindex="0"><thead><tr><th>来源</th><th>用途</th></tr></thead><tbody><tr><td><a href="https://www.rfc-editor.org/rfc/rfc1928.html" target="_blank" rel="noreferrer">RFC 1928: SOCKS Protocol Version 5</a></td><td>SOCKS5 方法协商、命令、地址类型与响应码的协议事实源</td></tr><tr><td><a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-9.3.6" target="_blank" rel="noreferrer">RFC 9110: HTTP Semantics, CONNECT</a></td><td>CONNECT 的隧道语义与安全限制</td></tr><tr><td><a href="https://www.rfc-editor.org/rfc/rfc9112.html" target="_blank" rel="noreferrer">RFC 9112: HTTP/1.1</a></td><td>HTTP/1.1 请求目标、消息边界与转发约束</td></tr><tr><td><a href="https://www.rfc-editor.org/rfc/rfc9293.html" target="_blank" rel="noreferrer">RFC 9293: Transmission Control Protocol</a></td><td>TCP 连接、字节流与关闭语义的标准依据</td></tr><tr><td><a href="https://www.rfc-editor.org/rfc/rfc1034.html" target="_blank" rel="noreferrer">RFC 1034: Domain Names - Concepts and Facilities</a></td><td>DNS 分层名字与解析概念的事实源</td></tr><tr><td><a href="https://www.rfc-editor.org/rfc/rfc4632.html" target="_blank" rel="noreferrer">RFC 4632: Classless Inter-domain Routing</a></td><td>IPv4 CIDR 前缀表示与匹配依据</td></tr><tr><td><a href="https://www.rfc-editor.org/rfc/rfc8446.html" target="_blank" rel="noreferrer">RFC 8446: TLS 1.3</a></td><td>解释 CONNECT 隧道内 TLS 仍由客户端与目标端点建立</td></tr><tr><td><a href="https://nodejs.org/api/net.html" target="_blank" rel="noreferrer">Node.js net and stream documentation</a></td><td>companion 使用的异步 TCP、allowHalfOpen 与 stream 行为依据</td></tr><tr><td><a href="https://docs.kernel.org/networking/tuntap.html" target="_blank" rel="noreferrer">Linux kernel TUN/TAP documentation</a></td><td>TUN 交付 IP 包、TAP 交付以太网帧的边界说明</td></tr></tbody></table><h2 id="安全与伦理边界" tabindex="-1">安全与伦理边界 <a class="header-anchor" href="#安全与伦理边界" aria-label="Permalink to &quot;安全与伦理边界&quot;">​</a></h2><p>代理技术具有双用途。本课程与配套的 mini-proxy <strong>仅面向你自己拥有或已经明确获得授权的环境</strong>，不教授流量伪装、证书劫持或绕过访问控制；全部自动化测试只连接 <code>127.0.0.1</code>，不访问公网。第 10 章会用一整节把&quot;测试全绿&quot;和&quot;可以安全对外提供服务&quot;分开讨论，并列出这个 mini-proxy 还没有实现的认证、访问控制、资源治理等能力——详见 <a href="./divergence.html">mini-proxy 与生产代理的差异</a>。</p>',13)])])}const f=r(d,[["render",n]]);export{T as __pageData,f as default};
